/* Passage-specific planning, briefing and forecast helpers. */
const currentSettingsKey='coastal-current-settings-v1';
let currentTimer,weatherSequence=0;
function saveCurrentSettings(){try{let x={};document.querySelectorAll('#form input[id],#form select[id]').forEach(e=>{if(e.checkValidity())x[e.id]=e.type==='checkbox'?e.checked:e.value;});localStorage.setItem(currentSettingsKey,JSON.stringify(x));}catch(e){}}
function restoreCurrentSettings(){try{const x=JSON.parse(localStorage.getItem(currentSettingsKey)||'{}');document.querySelectorAll('#form input[id],#form select[id]').forEach(e=>{if(!(e.id in x))return;let old=e.type==='checkbox'?e.checked:e.value;if(e.type==='checkbox')e.checked=!!x[e.id];else {e.value=x[e.id];if(!e.checkValidity()||(e.tagName==='SELECT'&&!e.value))e.value=old;}});}catch(e){}}
function scheduleCurrentUpdate(e){saveCurrentSettings();clearTimeout(currentTimer);if(!$('form').checkValidity())return;if(e.target.id==='uncertainty'&&trip){renderCurrentExtras();return;}const run=()=>{if(calculationBusy){currentTimer=setTimeout(run,300);return;}calculate().catch(()=>{});};currentTimer=setTimeout(run,500);}
function currentEligible(q){if($('arriveBy').checked){if(!$('arrivalDate').value||!$('arrivalTime').value)return false;try{if(q.end>eastern($('arrivalDate').value,$('arrivalTime').value))return false;}catch(e){return false;}}if($('daylightOnly').checked){for(let i=0;i<q.track.length;i+=10){const p=q.track[i];if(!NJPlanning.daylight(p.t,p.lat,p.lon))return false;}const p=q.track.at(-1);if(!NJPlanning.daylight(p.t,p.lat,p.lon))return false;}return true;}
function currentPoints(){const priority=new Set(['DEB2113','DEB2111','DEB2110','ACT4206','ACT4121','DEB2104','ACT4046','NYH1901','n03020','NYH1924','LIS1038','LIS1036','LIS1032','LIS1027','LIS1017','LIS1001','ACT2381','ACT1861','ACT1841','ACT1766','ACT1726','ACT1686']);let anchors=r.anchors.filter(a=>a.at>=0&&a.at<=r.total&&priority.has(a.station.id)).sort((a,b)=>a.at-b.at),out=[];for(const a of anchors){if(out.some(x=>x.station.id===a.station.id))continue;out.push(a);}if(!out.length){let nearby=r.anchors.filter(a=>a.at>=0&&a.at<=r.total).sort((a,b)=>a.at-b.at);for(const a of nearby)if(!out.some(x=>Math.abs(x.at-a.at)<8))out.push(a);}return out;}
function currentText(q){return q.mode==='unmodeled'?'Current not modeled':`${q.current.toFixed(1)} kt toward ${Math.round(q.dir)}° true · ${Math.abs(q.along).toFixed(1)} kt ${q.along>=0?'following':'opposing'}`;}
function renderCurrentExtras(){if(!trip)return;const selected=trip,points=currentPoints(),margin=+$('uncertainty').value;let entries=points.map(a=>{let t=P.atDistance(selected,a.at),q=P.sample(r,data,a.at,t,selected.speed),early=null,late=null;if(margin){try{early=P.sample(r,data,a.at,t-margin*60000,selected.speed);late=P.sample(r,data,a.at,t+margin*60000,selected.speed);}catch(e){}}return {a,t,q,early,late};});
 $('currentCritical').innerHTML=entries.length?'<div class="tableWrap"><table><thead><tr><th>Location</th><th>Expected arrival</th><th>Current along course</th><th>Early / late</th></tr></thead><tbody>'+entries.map((x,i)=>`<tr class="stationRowsLink" tabindex="0" data-current-index="${i}"><td>${x.a.station.name}</td><td>${fmt(x.t)}</td><td>${currentText(x.q)}</td><td>${margin?(x.early&&x.late?`${currentText(x.early)} / ${currentText(x.late)}`:'Prediction unavailable'):'Off'}</td></tr>`).join('')+'</tbody></table></div><p class="formHint">Early / late samples the predicted current at fixed location and shifted arrival time; it does not recalculate the full trip.</p>':'No modeled current stations on this passage.';
 $('currentCritical').querySelectorAll('[data-current-index]').forEach(row=>{const act=()=>{let e=entries[+row.dataset.currentIndex];inspect(e.a.at);if(map)map.plannerFocus([e.a.station.lat,e.a.station.lon]);};row.onclick=act;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act();}};});
 const delta=Math.round((selected.hours-r.total/selected.speed)*60),night=selected.track.some((q,i)=>i%10===0&&!NJPlanning.daylight(q.t,q.lat,q.lon));
 $('briefing').innerHTML=`<h3>${r.p[0].name} → ${r.p.at(-1).name}</h3><p>Depart ${fmt(selected.start)} · Arrive ${fmt(selected.end)}<br>${r.total.toFixed(1)} nm · ${duration(selected.hours)} underway · ${selected.speed} kt through water<br>${Math.abs(delta)} minutes ${delta<=0?'faster':'slower'} than without current · ${night?'Nighttime portions expected':'Daylight along sampled passage'}.</p>${r.unmodeledDistance?`<p>${r.unmodeledDistance.toFixed(1)} nm has no modeled current correction.</p>`:''}<h4>Critical current locations</h4><ul>${entries.map(x=>`<li tabindex="0" class="stationRowsLink" data-map-lat="${x.a.station.lat}" data-map-lon="${x.a.station.lon}">${x.a.station.name} · ${fmt(x.t)} · ${currentText(x.q)}${margin&&x.early&&x.late?` · ${margin} min early: ${currentText(x.early)}; ${margin} min late: ${currentText(x.late)}`:''}</li>`).join('')||'<li>No modeled current locations.</li>'}</ul><h4>Waypoint arrivals</h4><ul>${selected.arrivals.map((q,i)=>r.p[i].selectable!==false?`<li tabindex="0" class="stationRowsLink" data-map-lat="${r.p[i].lat}" data-map-lon="${r.p[i].lon}">${r.p[i].name} · ${fmt(q.t)} · ${currentText(q)} · ${q.sog.toFixed(1)} kt over ground · sea height: <span data-brief-sea="${i}">Loading forecast…</span> · <span data-brief-weather="${i}">Loading weather…</span></li>`:'').join('')}</ul><h4>Coast Guard notices</h4><p id="currentBriefNotices">Loading notice snapshot…</p><h4>Weather along the passage</h4><p id="currentWeather">Checking forecasts at estimated passage times…</p><p>Forecasts and currents are estimates; confirm updated marine forecasts and navigation information before departure.</p>`;
 updateCurrentWeather(selected,r); updateWaypointSeas(selected,r); updateCurrentBriefNotices();
}
async function updateCurrentWeather(selected,route){
 const seq=++weatherSequence,box=$('currentWeather');
 const samples=PassageWeather.samples({start:selected.start,end:selected.end,from:0,to:route.total,eta:s=>P.atDistance(selected,s),position:(s,t)=>P.sample(route,data,s,t,selected.speed),nameAt:p=>route.p.reduce((a,b)=>((a.lat-p.lat)**2+(a.lon-p.lon)**2)<((b.lat-p.lat)**2+(b.lon-p.lon)**2)?a:b).name});
 const all=await PassageWeather.collect(samples);
 if(seq!==weatherSequence||trip!==selected||!box.isConnected)return;
 box.textContent=PassageWeather.summary(all,fmt);
}
window.addEventListener('load',()=>{$('printBrief').onclick=()=>{document.body.classList.add('printBrief');window.print();};window.addEventListener('afterprint',()=>document.body.classList.remove('printBrief'));});

function updateCurrentBriefNotices(){const dest=$('currentBriefNotices'),summary=$('noticeSummary');if(!dest||!summary)return;const heads=[...document.querySelectorAll('#noticeList .noticeListItem b')].slice(0,8).map(e=>e.textContent);dest.textContent=(summary.textContent||$('noticeStatus').textContent||'Notice snapshot unavailable.')+(heads.length?' · '+heads.join('; '):'');}
window.addEventListener('current-notices-updated',updateCurrentBriefNotices);
